export const code = async (inputs) => {
  return {
    to: inputs.webhook_body.to,
    body: inputs.webhook_body.body,
    lead_id: inputs.webhook_body.lead_id,
    step_id: inputs.webhook_body.step_id
  };
};

export const code = async (inputs) => {
  // Convert text to TwiML for voicemail
  const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Joanna" language="en-US">
    ${inputs.body}
  </Say>
</Response>`;

  return { twiml: twiml };
};

export const code = async (inputs) => {
  const metric = {
    job: 'campaign_engine',
    instance: 'activepieces',
    labels: {
      channel: 'voicemail',
      step_id: inputs.step_id,
      lead_id: inputs.lead_id,
      status: inputs.call_status
    },
    value: 1,
    timestamp: Date.now()
  };

  console.log('Voicemail Metric:', metric);

  return metric;
};

export const code = async (inputs) => {
  return {
    status: 'success',
    channel: 'voicemail',
    call_sid: inputs.call_sid,
    lead_id: inputs.lead_id,
    step_id: inputs.step_id,
    sent_at: new Date().toISOString()
  };
};
